/**
 * @name Zip slip path traversal
 * @description Extracting zip files with user-controlled filenames can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // For ZipFile.extract method, the path is the second argument (index 1)
    exists(API::CallNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getMember("extract").getACall() and
      sink = call.getArg(1)
    )
    or
    // For ZipFile.extractall method, the path is the first argument (index 0)
    exists(API::CallNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getMember("extractall").getACall() and
      sink = call.getArg(0)
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Zip slip path traversal from $@.", source.getNode(), "user input"

/**
 * @name Excel formula injection
 * @description User input flowing into Excel formulas without sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/excel-formula-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FormulaInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for cell value assignments in openpyxl
    exists(DataFlow::CallCfgNode call |
      // openpyxl.cell.cell.Cell.value setter
      call = API::moduleImport("openpyxl").getMember("cell").getMember("cell").getMember("Cell").getMember("value").getACall() and
      sink = call.getArg(0)
    )
  }
}

module FormulaInjectionFlow = TaintTracking::Global<FormulaInjectionConfig>;
import FormulaInjectionFlow::PathGraph

from FormulaInjectionFlow::PathNode source, FormulaInjectionFlow::PathNode sink
where FormulaInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Excel formula injection from $@.", source.getNode(), "user input"
